\label{prop:julia_jordan}
    Let $f$ be a rational map whose Julia set is homeomorphic to $\mathbb S^1$. There exists a quasiconformal map $g\colon \widehat \mathbb{C}\to \widehat \mathbb{C}$ that maps each Fatou component of $f$ onto a disk if and only if
    \begin{itemize}
        \item $f$ has a parabolic periodic point of multiplicity $3$ or
        \item $f$ is hyperbolic.
    \end{itemize}

\label{corollary:unicritical}
      Let $f(z)=z^d+c$, $d\geq 2$, be a geometrically finite unicritical polynomial with non-empty bounded Fatou set. There exists a quasiconformal map of $\mathbb{C}$ that maps each bounded Fatou component of $f$ onto a disk if and only if 
    \begin{itemize}
        \item $f$ has a parabolic periodic point of multiplicity $3$ or
        \item $f$ is hyperbolic and all bounded Fatou components have disjoint closures.
    \end{itemize}

\label{corollary:degree2}
    The conditions of Corollary \ref{corollary:unicritical} are equivalent to the following two conditions, respectively:
    \begin{itemize}
        \item $c$ is a period-doubling bifurcation point or
        \item $c$ is in the main hyperbolic component of a primitive Multibrot copy.
    \end{itemize}

\label{theorem:qr_germ}
    Let $K_1,K_2\subset \widehat \mathbb{C}$ be quasicircles such that $K_1\cap K_2=\{0\}$. Then there exists a quasiconformal map $\Phi\colon \widehat \mathbb{C}\to \widehat \mathbb{C}$ that maps $K_1$ and $K_2$ onto two tangent circles if and only if there exists a map $f$ in a neighborhood of $0$ that  fixes $0$ and is quasiconformally conjugate to a parabolic germ such that
    \begin{enumerate}[label=\normalfont(\arabic*)]
        \item for $j=1,2$ there exists an attracting (resp.\ repelling) petal $P_j$, where $P_1$ and $P_2$ correspond to distinct attraction or repulsion vectors of the parabolic germ, and
        \item for $i=1,2$ the set $K_i\cap (P_j\cup \{0\})$ contains a Jordan arc $E_{ij}$ with an endpoint at $0$ that satisfies $f(E_{ij})\subset E_{ij}$ (resp.\ $f^{-1}(E_{ij})\subset E_{ij}$).
    \end{enumerate}

\label{lemma:avoid_petals}
    Let $f$ be a parabolic germ at $0$. Let $U\subset \widehat \mathbb{C}$ be a Jordan region with $0\in \partial U$ such that $U$ is disjoint from all attracting (resp.\ repelling) petals. 
    \begin{enumerate}[label=\normalfont(\arabic*)]
        \item Then $U$ is not a quasidisk. Moreover, each arc of $\partial U$ that contains $0$ in its interior is not a quasiarc.
        \item\label{lemma:avoid_petals:2} Suppose that $g$ is a holomorphic map defined in a neighborhood of a closed Jordan region $\overline{W}$ such that $g|_W$ is injective, $g(W)\subset U$, and $0\in \partial g(W)$. Then each arc $A\subset \partial W$ with $0$ lying in the interior of $g(A)$ is not a quasiarc.
    \end{enumerate}

By Lemma \ref{lemma:germ_tangent_reduction}, we may assume that $K_1=\mathbb{R}\cup \{\infty\}$. Without loss of generality suppose that $K_2$ is in the closure of the lower half-plane. Since the real line $\mathbb{R}$ is locally preserved under $f$ near $0$, we conclude that $P_1$ and $P_2$ are parabolic petals in the direction of the positive and negative real axis, respectively. By replacing $f$ with its inverse if necessary, we may assume that $P_1$ is an attracting petal in the direction of the positive real axis. Thus, $f$ has an expansion at $0$ of the form
        $$f(z)=z+az^{n+1}+O(z^{n+2}),$$
        where $a<0$ and $n\in \mathbb{N}$.  We conjugate $f$ by $z\mapsto 1/z$ to the parabolic germ $g$ at $\infty$ with expansion
        $$g(z)=z-\frac{a}{z^{n-1}}+O(z^{-n}).$$

        Let $J$ be the image of $K_2$ under $z\mapsto 1/z$. Then $J$ contains an arc $J^+$ with an endpoint at $\infty$ that is invariant and is attracted to $\infty$ by $g$ in the direction of the positive real axis. Similarly, $J$ contains an arc $J^-$ with an endpoint at $\infty$ that is invariant and is attracted to $\infty$ by $g$ or $g^{-1}$ in the direction of the negative real axis. In order to prove that there exists a quasiconformal homeomorphism of $\widehat \mathbb{C}$ that maps $\mathbb{R}$ and $J\setminus \{\infty\}$ to parallel lines, by Theorem \ref{theorem:tangent:graph} it suffices to prove that there exists $L\geq 1$ such that
        \begin{align}\label{theorem:germ_tangent:inclusion}
        J\setminus \{\infty\}\subset \{(x,y)\in \mathbb{R}^2:  L^{-1}(1+|x|)^{-n+1}\leq y\leq L(1+|x|)^{-n+1}\}.
        \end{align}
        It suffices to show the inclusion for the arcs $J^+$ and $J^-$. We focus on $J^+$.

        Let $w = \phi(z) = z^n/(-na)$, which maps the sector $\Delta=\{re^{i\theta}: r>0,\,\, |\theta|<\pi/n\}$ conformally onto the slit plane $\mathbb{C}\setminus (-\infty,0]$.  We set
        $$G(w)= \phi \circ g\circ \phi^{-1}(w) = w+1+o(1)$$ 
        as $w\to\infty$. The calculation of the expansion can be found in \cite{Milnor:dynamics}*{(10.2), p.~107}.  Let $R>0$ be sufficiently large so that 
        \begin{align}\label{eqn:parabolicestimate}
            |G(w)-w-1|<1/4. 
        \end{align}
        In particular, if $w\in \mathbb H_{>R}$, then $\operatorname{Re}(G(w))>\operatorname{Re}(w)+3/4$, so $G(\mathbb H_{>R})\subset \mathbb H_{>R}$. Note that for any $k\in\mathbb{N}$ the map $G^{\circ k}\colon \mathbb H_{>R}\to \mathbb H_{>R}$ is a conformal embedding. Since the real axis is locally invariant under $G$ near $\infty$, we may consider an even larger $R>0$ so that $G^{-1}(\mathbb H_{>R}\cap \mathbb{R})\subset \mathbb{R}$. This implies that $G(\mathbb H_{>R}\cap \mathbb H)\subset \mathbb H_{>R}\cap \mathbb H$.

        Since $J^+$ is invariant under $g$ and is attracted to $\infty$ in the direction of the positive real axis, by replacing it with an iterate if necessary (see Lemma \ref{lemma:arc_invariant_general}), we may assume that $J^+\subset \Delta$. Moreover, each arbitrarily small sector at $0$ that contains the positive real axis contains some iterate of $J^+$ under $g$. Thus, the same is true for iterates of $\phi(J^+)$ under $G$ (given that $\phi$ is a power map and maps small sectors to small sectors). Thus, by passing to an iterate of $J^+$ under $g$, we may assume that $\phi(J^+)\subset \mathbb H_{>R}$. 

        Let $p_0\in \mathbb{R}\cap \mathbb H_{>R}$ and  $p_k=G(p_{k-1}) = G^{\circ k}(p_0)$, $k\in \mathbb{N}$. Also, let $q_0 \in \phi(J^+)$ and $q_k=G(q_{k-1}) = G^{\circ k}(q_0)$, $k\in \mathbb{N}$. For $k\in \mathbb{N}$ denote by $J^+(k)$ the subarc of $\phi(J^+)$ from $q_{k-1}$ to $q_k$. Consider a ball $B$ such that $\overline{B}\subset \mathbb H_{>R}$ and $[p_0,p_1]\cup J^+(1) \subset B$.  Note that there exists $t>1$ such that $tB\subset \mathbb H_{>R}$. By Koebe's distortion theorem \cite{Pommerenke:conformal}*{Theorem 1.3}, we have
        \begin{align}\label{theorem:germ:k1}
            |G^{\circ k}(w_1)- G^{\circ k}(w_2)| \simeq  |(G^{\circ k})'(p_0)|\cdot  |w_1-w_2|
        \end{align}
        for all distinct $w_1,w_2\in B$ and $k\in \mathbb{N}$. Thus, for each $w\in J^+(1)$ and $k\in \mathbb{N}$ we have
        $$\frac{|p_k -  G^{\circ k}(w)|}{|p_k-p_{k+1}|} \simeq  \frac{|p_0-w|}{|p_0-p_1|}.$$
        By compactness, we have $|p_0-w|\simeq 1$ for $w\in J^+(1)$, so 
        $$\frac{|p_k -  G^{\circ k}(w)|}{|p_k-p_{k+1}|} \simeq 1$$
        for all $k\in \mathbb{N}$ and $w\in J^+(1)$. Also, by {\eqref{eqn:parabolicestimate}}, we have 
        \begin{align}\label{theorem:germ:k2}
            3/4\leq |p_k-p_{k+1}| \leq 5/4 
        \end{align}
        for all $k\in \mathbb{N}\cup\{0\}$. Thus, 
        $$ |p_k-G^{\circ k}(w)| \simeq 1$$
        for all $k\in \mathbb{N}$ and $w\in J^+(1)$. This implies that $\operatorname{Im} (w)\lesssim 1$ for all $w\in J^+(k)$, $k\in \mathbb{N}$.

