    $$\operatorname{dist}(J_{i,n},J_{i,m}) \geq \delta \quad \text{for $i=1$ or $i=2$.}$$
    Consider the space $X$ of compact subsets of $\partial \mathbb{D}\times \partial \mathbb{D}$ equipped with the Hausdorff metric. Then for $n,m\in I$ with $a_n\neq a_m$, any two points 
    $$J_{1,n}\times J_{2,n},\,\, J_{1,m}\times J_{2,m}\in X$$
    have distance at least $\delta$. Since $X$ is compact, we conclude that the set $\{a_n:n\in I\}$ is finite. Thus, there exist $n\neq m$ such that $f^{\circ n}(a_0)=f^{\circ m}(a_0)$ and $a_0$ is pre-periodic, as desired.

\label{lem:expandprep}
     Let $f$ be a geometrically finite rational map, and $U$ be a non-periodic Fatou component such that $V = f(U)$ is a fixed Fatou component. Suppose that both $U, V$ are Jordan regions, $\partial U$ contains no parabolic point, and $\partial V$ contains a unique parabolic fixed point $a$ of parabolic multiplicity $2$ such that $V$ is an immediate basin of $a$. Assume further that $\deg_z(f^{\circ n})\ge2$ whenever $z\in\partial U$ and $f^{\circ n}(z)=a$ for some $n\in \mathbb{N}$.
     Let 
     \begin{align*}
    \mathcal{A}' \coloneqq P(f) \cap \partial V, &\text{ and }
    \mathcal{B}'\coloneqq f^{-1}(\mathcal{A}') \cap \partial V\\
    \mathcal{A} \coloneqq f^{-1}(\mathcal{A}') \cap \partial U, &\text{ and }  \mathcal{B} \coloneqq f^{-1}(\mathcal{B}') \cap \partial U.
    \end{align*}
    Let $\{\gamma_i\}$ and $\{I_j\}$ be the components of $\partial U\setminus \mathcal A$ and $\partial U\setminus \mathcal B$, respectively.
    Let $S\colon \partial U \rightarrow \partial U$ be an orientation-preserving covering that is a lift of $f\colon \partial V \rightarrow \partial V$ under $f\colon \partial U \rightarrow \partial V$, i.e., $S$ satisfies
     $$
     f\circ S = f \circ f.
     $$
    Then there exist open neighborhoods $N_i$ of $\gamma_i$ and $D_j$ of $I_j$ so that
    \begin{itemize}
        \item (Disjointedness) the sets $\{D_j\}$ are pairwise disjoint,
        \item (Containment) if $I_j \subset \gamma_k$, then $D_j \subset N_k$,
        \item (Conformality) if $S(I_j) = \gamma_i$, then $S\colon D_j \rightarrow N_{i}$ is conformal.
    \end{itemize}
